// Normalise a Slack message event into a question for the twin.
const ev = $input.first().json.event || $input.first().json;
const text = (ev.text || '').trim();
const isQuestion = /\?|\b(how|what|when|why|can you|could you|please)\b/i.test(text);
return [{ json: { channel: ev.channel || 'YOUR_SLACK_CHANNEL_ID',
  user: ev.user || '', threadTs: ev.thread_ts || ev.ts || '',
  text, isQuestion, receivedAt: new Date().toISOString() } }];

// MEMORY LAYER PLACEHOLDER — no live vector DB is connected yet.
// When Siva connects a vector store, replace this node with a real
// retriever that returns [{source, snippet, score}] for $json.text.
// Until then it returns an EMPTY retrieval list on purpose: the agent
// must say it has no source instead of inventing one.
return [{ json: { ...$input.first().json, retrieved: [],
  memoryNote: 'No vector store connected yet — answer from general knowledge of Siva only, and say so.' } }];

