// Parse the agent JSON. On parse failure, force escalation — never guess.
const raw = $input.first().json.output || $input.first().json.text || '';
const prev = $('Extract Question').first().json;
let p = {};
try { p = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { p = m ? JSON.parse(m[0]) : {}; } catch (e2) { p = {}; }
}
const needsApproval = p.needsApproval === true ||
  /\b(I will|I'll|I promise|confirmed|agreed|deadline is|I can do that by)\b/i.test(p.answer || '');
return [{ json: { ...prev, answer: p.answer || '',
  confidence: typeof p.confidence === 'number' ? p.confidence : 0,
  sources: p.sources || [], reason: p.reason || '',
  needsEscalation: p.needsEscalation === true || (typeof p.confidence === 'number' && p.confidence < 0.7),
  needsApproval } }];

